#include <vector>
#include <string>

class Student {
public:
    std::string name;
    int roll;
    double gpa;
    Student(std::string n, int r, double g) : name(n), roll(r), gpa(g) {}
};

class Manager {
private:
    std::vector<Student> db;
public:
    void addStudent(std::string n, int r, double g) {
        db.push_back(Student(n, r, g));
    }
    void printBest() {
        if (db.empty()) return;
        Student best = db[0];
        for (auto& s : db) {
            if (s.gpa > best.gpa) best = s;
        }
        std::cout << best.name << "\n";
    }
};

int main() {
    Manager m;
    m.addStudent("Alice", 1, 3.5);
    m.addStudent("Bob", 2, 4.0);
    m.printBest();
    return 0;
